// Lấy dữ liệu file đính kèm
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'attachment_0');

// Chuyển thành Base64
$input.item.json.base64Data = binaryData.toString('base64');

// Lấy thông tin loại file
const fileInfo = $input.item.binary.attachment_0;
if (fileInfo) {
  // Lấy mimeType (vd: 'application/pdf', 'image/jpeg') để cung cấp cho Gemini
  $input.item.json.mimeType = fileInfo.mimeType;

  // Lấy đuôi file (vd: 'pdf', 'jpg') để dùng cho việc upload lên Drive
  if (fileInfo.fileExtension) {
    $input.item.json.fileExtension = fileInfo.fileExtension;
  } else if (fileInfo.fileName && fileInfo.fileName.includes('.')) {
    $input.item.json.fileExtension = fileInfo.fileName.split('.').pop();
  } else if (fileInfo.mimeType) {
    $input.item.json.fileExtension = fileInfo.mimeType.split('/').pop();
  } else {
    $input.item.json.fileExtension = "unknown";
  }
}

return $input.item;

const emailContent = $input.item.json.text || "";

// 1. Tìm cái link lẩn khuất trong email
const linkRegex = /(https?:\/\/[^\s]+)/;
let match = emailContent.match(linkRegex);

let finalUrl = null;

if (match && match[1]) {
  let rawUrl = match[1];

  // Dọn dẹp: Cắt bỏ mấy dấu ngoặc kép hoặc ký tự lạ lỡ dính vào cuối link
  rawUrl = rawUrl.replace(/["'>)\]]/g, '');

  // 2. Kiểm tra xem có phải link Google Drive không
  if (rawUrl.includes("drive.google.com/file/d/")) {

    // Dùng Regex móc cái File ID nằm giữa /d/ và /view ra
    const idMatch = rawUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
    if (idMatch && idMatch[1]) {
      const fileId = idMatch[1];
      // Ép thành link tải trực tiếp
      finalUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;
    }

  } else if (rawUrl.includes("drive.google.com/open?id=")) {
      // Trường hợp link Drive kiểu cũ
      const idMatch = rawUrl.match(/id=([a-zA-Z0-9_-]+)/);
      if (idMatch && idMatch[1]) {
          const fileId = idMatch[1];
          finalUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;
      }
  } else {
    // 3. Nếu là link trực tiếp bình thường (thì giữ nguyên
    finalUrl = rawUrl;
  }
}

// Lưu link đã xử lý để truyền cho node HTTP Request tải về
$input.item.json.invoice_url = finalUrl;

return $input.item;

// Lấy dữ liệu file từ hộp 'data' (do HTTP Request tạo ra)
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');

// Chuyển thành Base64
$input.item.json.base64Data = binaryData.toString('base64');

// Lấy thông tin metadata
const fileInfo = $input.item.binary.data;

if (fileInfo) {
  let currentMimeType = fileInfo.mimeType;

  // XỬ LÝ LỖI GOOGLE DRIVE: Nếu MIME bị vô danh (octet-stream), ép về PDF
  if (currentMimeType === 'application/octet-stream' || !currentMimeType) {
    $input.item.json.mimeType = 'application/pdf';
    $input.item.json.fileExtension = 'pdf';
  } 
  // Nếu MIME đã chuẩn chỉnh (như image/png), thì xử lý bình thường
  else {
    $input.item.json.mimeType = currentMimeType;

    if (fileInfo.fileExtension) {
      $input.item.json.fileExtension = fileInfo.fileExtension;
    } else if (fileInfo.fileName && fileInfo.fileName.includes('.')) {
      $input.item.json.fileExtension = fileInfo.fileName.split('.').pop();
    } else if (currentMimeType) {
      $input.item.json.fileExtension = currentMimeType.split('/').pop();
    } else {
      $input.item.json.fileExtension = "unknown";
    }
  }
}

return $input.item;

